ALTER TABLE public.staynas_room_catalogue_types ADD COLUMN IF NOT EXISTS amenities text[] NOT NULL DEFAULT '{}'; INSERT INTO storage.buckets (id, name, public, file_size_limit, allowed_mime_types) VALUES ('room-images', 'room-images', true, 10485760, ARRAY['image/jpeg','image/png','image/webp','image/avif']) ON CONFLICT (id) DO UPDATE SET public = EXCLUDED.public, file_size_limit = EXCLUDED.file_size_limit, allowed_mime_types = EXCLUDED.allowed_mime_types; DROP POLICY IF EXISTS "Platform admins upload room images" ON storage.objects; CREATE POLICY "Platform admins upload room images" ON storage.objects FOR INSERT TO authenticated WITH CHECK (bucket_id = 'room-images' AND EXISTS (SELECT 1 FROM public.staynas_platform_admins a WHERE a.user_id = auth.uid())); DROP POLICY IF EXISTS "Platform admins update room images" ON storage.objects; CREATE POLICY "Platform admins update room images" ON storage.objects FOR UPDATE TO authenticated USING (bucket_id = 'room-images' AND EXISTS (SELECT 1 FROM public.staynas_platform_admins a WHERE a.user_id = auth.uid())) WITH CHECK (bucket_id = 'room-images' AND EXISTS (SELECT 1 FROM public.staynas_platform_admins a WHERE a.user_id = auth.uid())); DROP POLICY IF EXISTS "Platform admins delete room images" ON storage.objects; CREATE POLICY "Platform admins delete room images" ON storage.objects FOR DELETE TO authenticated USING (bucket_id = 'room-images' AND EXISTS (SELECT 1 FROM public.staynas_platform_admins a WHERE a.user_id = auth.uid())); DROP POLICY IF EXISTS "Public read room images" ON storage.objects; CREATE POLICY "Public read room images" ON storage.objects FOR SELECT TO anon, authenticated USING (bucket_id = 'room-images'); COMMENT ON COLUMN public.staynas_room_catalogue_types.amenities IS 'Canonical guest-facing amenities for this room definition.';